-- Catálogo de panadería, hojaldres, galletas y repostería individual (45 productos).
-- Fuente: Daliza_Panaderia_Hojaldres_Dataset.xlsx. Se ejecuta UNA vez en Supabase → SQL Editor.
-- • Es idempotente: si un producto ya existe (mismo slug) no se toca, así no pisa ediciones hechas en el admin.
-- • Precio vacío (la web muestra "Consultar"). Se pueden poner desde el admin.
-- • Sin foto: usan el logo como imagen provisional hasta subir la foto desde el admin.
-- • Disponibilidad: se asignan a TODAS las sedes activas; se ajusta por producto desde el admin.
-- • 'hojaldres' no es un servicio del sitio, así que se publica dentro de Panadería; galletas va en Repostería.

begin;

on conflict (slug) do nothing;

select p.id, l.id
from public.products p
cross join public.locations l
where l.active
  and p.slug in ('pan-alinado', 'pan-de-queso', 'pan-7-granos', 'pan-galleta', 'mogolla', 'roscones', 'pan-de-breva', 'pan-almohabanado', 'roscon-de-coco', 'pan-de-bono', 'almojabana', 'junior', 'muffins', 'cruasan-de-chocolate', 'cruasan-de-bocadillo', 'cruasan-de-jamon', 'merengues', 'brownies', 'tostadas', 'torta-de-mazorca', 'mantecada', 'roscas', 'galleta-de-avena', 'galleta-con-chips', 'galleta-pepas', 'galleta-de-chocolate-blanco', 'galleta-de-chocolate-negro', 'galleta-rizada', 'galleta-punta-chocolate', 'rosca-de-vainilla', 'galleta-munecos', 'alfajor-de-mani', 'alfajor-de-coco', 'trufas', 'hojaldre-de-arequipe-y-queso', 'hojaldre-de-bocadillo-y-queso', 'hojaldre-de-pastelera-y-bocadillo', 'palito-de-queso', 'danesa-de-breva', 'tiples-de-bocadillo-y-queso', 'hojaldre-de-bocadillo', 'pastel-de-carne', 'pastel-de-pollo', 'corazones', 'pastel-hawaiano')
on conflict do nothing;

commit;
