insert into public.products (slug, name, description, description_long, servicio, categoria, price, active, sort_order)
values
  ('pan-alinado', 'Pan aliñado', 'Pan aliñado tradicional de la línea de panadería Daliza.', 'Un clásico de panadería de perfil casero y versátil, ideal para acompañar desayunos, onces o cualquier momento del día. El sabor cotidiano elevado a un clásico Daliza: un pan aliñado reconfortante, perfecto para compartir recién servido y convertir cualquier pausa en un momento especial.', 'panaderia', 'panes tradicionales', null, true, 101),
  ('pan-de-queso', 'Pan de queso', 'Pan de queso de la línea de panadería Daliza.', 'Una opción de panadería con el queso como protagonista, pensada para disfrutar en desayunos, onces o como acompañamiento. Una propuesta cálida y apetecible donde el carácter del queso se convierte en protagonista. Ideal para disfrutar solo o acompañar tus momentos favoritos con un sabor que siempre invita a repetir.', 'panaderia', 'panes con queso', null, true, 102),
  ('pan-7-granos', 'Pan 7 granos', 'Pan especial de 7 granos.', 'Pan de la línea especial elaborado bajo el concepto de siete granos, pensado para quienes prefieren alternativas con un perfil más cereal. Una opción especial para quienes buscan variedad en su panadería diaria: siete granos reunidos en una propuesta equilibrada, versátil y perfecta para comenzar el día con un sabor diferente.', 'panaderia', 'panes integrales y especiales', null, true, 103),
  ('pan-galleta', 'Pan galleta', 'Pan galleta tradicional.', 'Producto clásico de panadería identificado como pan galleta, ideal para desayunos y onces. Un clásico de vitrina con ese encanto sencillo que acompaña generaciones. El pan galleta Daliza es una elección versátil, cercana y perfecta para disfrutar a cualquier hora.', 'panaderia', 'panes tradicionales', null, true, 104),
  ('mogolla', 'Mogolla', 'Mogolla tradicional de panadería.', 'Una preparación clásica de panadería, ideal para acompañar bebidas calientes, desayunos u onces. Tradición en cada porción: una mogolla pensada para acompañar el café, compartir en familia y disfrutar esos pequeños momentos que saben a panadería recién hecha.', 'panaderia', 'panes tradicionales', null, true, 105),
  ('roscones', 'Roscones', 'Roscones tradicionales de panadería.', 'Roscones de la línea clásica Daliza, pensados para desayunos, onces y momentos de antojo. Un clásico que nunca pierde su encanto. Los roscones Daliza combinan tradición y antojo en una opción ideal para acompañar una bebida caliente o compartir en cualquier momento.', 'panaderia', 'roscones y roscas', null, true, 106),
  ('pan-de-breva', 'Pan de breva', 'Pan dulce con breva.', 'Una alternativa de panadería dulce donde la breva aporta un perfil frutal y tradicional. Un encuentro entre la tradición de la panadería y el carácter frutal de la breva. Una propuesta dulce y especial para quienes disfrutan sabores clásicos con un toque diferente.', 'panaderia', 'panes dulces', null, true, 107),
  ('pan-almohabanado', 'Pan almohabanado', 'Pan especial identificado como almohabanado.', 'Producto de la línea de panadería especial registrado en la hoja de producción como pan almohabanado. Una referencia especial del portafolio Daliza, pensada para quienes disfrutan descubrir sabores y preparaciones propias de una panadería con tradición.', 'panaderia', 'panes especiales', null, true, 108),
  ('roscon-de-coco', 'Roscón de coco', 'Roscón con sabor a coco.', 'Roscón de la línea dulce con presencia de coco, ideal para acompañar desayunos u onces. Un roscón con un giro tropical: el coco aporta una nota especial a este clásico de panadería y lo convierte en una opción irresistible para acompañar tus momentos de antojo.', 'panaderia', 'roscones y roscas', null, true, 109),
  ('pan-de-bono', 'Pan de bono', 'Pan de bono tradicional.', 'Clásico producto de panadería colombiana, ideal para disfrutar como acompañamiento o en una pausa del día. Un imprescindible de la panadería colombiana. El pan de bono Daliza es perfecto para disfrutar en cualquier momento y acompañar con tu bebida favorita.', 'panaderia', 'panes con queso', null, true, 110),
  ('almojabana', 'Almojábana', 'Almojábana tradicional.', 'Clásico de panadería colombiana, ideal para desayunos, onces y acompañamientos. Un sabor que se siente cercano desde el primer bocado. La almojábana Daliza celebra la tradición colombiana en una propuesta perfecta para compartir o disfrutar recién servida.', 'panaderia', 'panes con queso', null, true, 111),
  ('junior', 'Junior', 'Producto de panadería especial Junior.', 'Referencia de la línea de panadería Daliza registrada comercialmente como Junior. Una referencia especial del portafolio Daliza creada para ampliar la variedad de nuestra vitrina y ofrecer una alternativa diferente para tus momentos de antojo.', 'panaderia', 'panes especiales', null, true, 112),
  ('muffins', 'Muffins', 'Muffin individual de repostería.', 'Una opción individual de repostería ideal para acompañar café, regalar o disfrutar como antojo. Un pequeño placer pensado para grandes antojos. Nuestros muffins son perfectos para acompañar el café, consentirte durante el día o sumar un detalle dulce a cualquier ocasión.', 'reposteria', 'repostería individual', null, true, 113),
  ('cruasan-de-chocolate', 'Cruasán de chocolate', 'Cruasán de chocolate.', 'Una pieza de la línea de cruasanes Daliza con perfil de chocolate, ideal para desayunos, onces o antojos. Una propuesta de panadería hojaldrada con el toque especial de chocolate. Ideal para disfrutar en cualquier momento y convertir una pausa cotidiana en un antojo memorable.', 'panaderia', 'cruasanes', null, true, 114),
  ('cruasan-de-bocadillo', 'Cruasán de bocadillo', 'Cruasán de bocadillo.', 'Una pieza de la línea de cruasanes Daliza con perfil de bocadillo, ideal para desayunos, onces o antojos. Una propuesta de panadería hojaldrada con el toque especial de bocadillo. Ideal para disfrutar en cualquier momento y convertir una pausa cotidiana en un antojo memorable.', 'panaderia', 'cruasanes', null, true, 115),
  ('cruasan-de-jamon', 'Cruasán de jamón', 'Cruasán de jamón.', 'Una pieza de la línea de cruasanes Daliza con perfil de jamón, ideal para desayunos, onces o antojos. Una propuesta de panadería hojaldrada con el toque especial de jamón. Ideal para disfrutar en cualquier momento y convertir una pausa cotidiana en un antojo memorable.', 'panaderia', 'cruasanes', null, true, 116),
  ('merengues', 'Merengues', 'Merengues de repostería.', 'Preparación dulce de la línea de repostería Daliza, ideal para compartir o disfrutar como un antojo ligero. Delicados, dulces y perfectos para compartir. Los merengues Daliza son ese detalle sencillo que aporta un toque especial a una mesa de postres o a un momento de antojo.', 'reposteria', 'repostería individual', null, true, 117),
  ('brownies', 'Brownies', 'Brownie de chocolate.', 'Clásico de repostería con protagonismo del chocolate, ideal para postres, regalos y momentos de antojo. Para quienes creen que el chocolate nunca es demasiado: un brownie intenso y reconfortante, perfecto para disfrutar solo, acompañar con una bebida o convertir cualquier momento en algo más especial.', 'reposteria', 'chocolate y brownies', null, true, 118),
  ('tostadas', 'Tostadas', 'Tostadas de panadería.', 'Tostadas de la línea Daliza, una opción práctica para desayunos, acompañamientos y meriendas. Crujientes y versátiles, las tostadas Daliza son ese básico que combina con todo y acompaña desayunos, meriendas y momentos de café con un toque tradicional.', 'panaderia', 'tostadas', null, true, 119),
  ('torta-de-mazorca', 'Torta de mazorca', 'Torta de mazorca.', 'Torta especial de la línea de repostería Daliza con la mazorca como elemento distintivo de la receta. Una propuesta con identidad propia que lleva la mazorca al universo de la repostería. Ideal para quienes disfrutan sabores tradicionales transformados en una experiencia dulce y diferente.', 'reposteria', 'tortas y ponqués', null, true, 120),
  ('mantecada', 'Mantecada', 'Mantecada tradicional.', 'Clásico de repostería de perfil tradicional, ideal para acompañar bebidas calientes y compartir. Un clásico sencillo y reconfortante que siempre encuentra un lugar en la mesa. La mantecada Daliza es perfecta para acompañar el café y disfrutar el sabor de lo tradicional.', 'reposteria', 'tortas y ponqués', null, true, 121),
  ('roscas', 'Roscas', 'Roscas tradicionales de panadería.', 'Roscas de la línea clásica Daliza, ideales para desayunos, onces y acompañamientos. Una forma clásica de disfrutar la panadería de siempre. Las roscas Daliza acompañan perfectamente una bebida caliente y esos momentos de pausa que merecen algo rico.', 'panaderia', 'roscones y roscas', null, true, 122),
  ('galleta-de-avena', 'Galleta de avena', 'Galleta de avena.', 'Galleta de la línea Daliza con avena como sabor distintivo, pensada para acompañar bebidas o disfrutar como snack dulce. Una galleta con personalidad propia, donde la avena aporta un perfil clásico y reconfortante. Perfecta para acompañar el café, llevar contigo o disfrutar cuando aparece el antojo.', 'reposteria', 'galletas', null, true, 123),
  ('galleta-con-chips', 'Galleta con chips', 'Galleta con chips.', 'Galleta de la línea Daliza con chips como elemento destacado, ideal para acompañar bebidas y momentos de antojo. Una galleta creada para quienes disfrutan encontrar pequeños toques de sabor en cada bocado. Perfecta para acompañar el café o regalarte una pausa dulce durante el día.', 'reposteria', 'galletas', null, true, 124),
  ('galleta-pepas', 'Galleta pepas', 'Galleta pepas.', 'Referencia clásica de galletas Daliza registrada como galleta pepas. Una galleta clásica del portafolio Daliza, pensada para quienes buscan un antojo sencillo, delicioso y perfecto para acompañar cualquier momento del día.', 'reposteria', 'galletas', null, true, 125),
  ('galleta-de-chocolate-blanco', 'Galleta de chocolate blanco', 'Galleta de chocolate blanco.', 'Galleta con perfil de chocolate blanco, ideal para acompañar bebidas o disfrutar como antojo. Dulce, delicada y pensada para quienes aman el chocolate blanco. Una galleta que convierte una pausa cotidiana en un pequeño momento de indulgencia.', 'reposteria', 'galletas', null, true, 126),
  ('galleta-de-chocolate-negro', 'Galleta de chocolate negro', 'Galleta de chocolate negro.', 'Galleta con protagonismo del chocolate negro, ideal para quienes prefieren sabores más intensos. Una opción de carácter más intenso para verdaderos amantes del chocolate. Perfecta para acompañar el café o disfrutar cuando buscas un antojo con personalidad.', 'reposteria', 'galletas', null, true, 127),
  ('galleta-rizada', 'Galleta rizada', 'Galleta rizada.', 'Galleta de la línea tradicional Daliza con presentación rizada. Una presentación clásica y llamativa que hace de cada galleta un pequeño detalle especial. Ideal para compartir, acompañar bebidas o disfrutar durante el día.', 'reposteria', 'galletas', null, true, 128),
  ('galleta-punta-chocolate', 'Galleta punta chocolate', 'Galleta con punta de chocolate.', 'Galleta de la línea Daliza terminada con chocolate como detalle distintivo. Una galleta clásica con un toque que marca la diferencia: su acabado de chocolate añade una nota irresistible y la convierte en una opción perfecta para acompañar cualquier antojo.', 'reposteria', 'galletas', null, true, 129),
  ('rosca-de-vainilla', 'Rosca de vainilla', 'Rosca de vainilla.', 'Rosca dulce con perfil de vainilla, incorporada a la línea de panadería Daliza. Aromática, delicada y familiar, la rosca de vainilla es una opción perfecta para compartir y acompañar el café con un sabor clásico que siempre se disfruta.', 'panaderia', 'roscones y roscas', null, true, 130),
  ('galleta-munecos', 'Galleta muñecos', 'Galletas en forma de muñecos.', 'Galletas de presentación lúdica y decorativa, ideales para compartir y para ocasiones especiales. Una galleta que también entra por los ojos. Su presentación en forma de muñecos aporta un toque divertido y especial, ideal para compartir, regalar o sorprender a los más pequeños.', 'reposteria', 'galletas', null, true, 131),
  ('alfajor-de-mani', 'Alfajor de maní', 'Alfajor de maní.', 'Alfajor de la línea de repostería Daliza con maní como sabor distintivo. Una propuesta dulce y especial donde el maní aporta personalidad a un clásico de repostería. Perfecto para regalar, compartir o disfrutar cuando quieres darte un gusto.', 'reposteria', 'alfajores', null, true, 132),
  ('alfajor-de-coco', 'Alfajor de coco', 'Alfajor de coco.', 'Alfajor de la línea de repostería Daliza con coco como sabor distintivo. Una propuesta dulce y especial donde el coco aporta personalidad a un clásico de repostería. Perfecto para regalar, compartir o disfrutar cuando quieres darte un gusto.', 'reposteria', 'alfajores', null, true, 133),
  ('trufas', 'Trufas', 'Trufas de repostería.', 'Pequeñas piezas dulces de la línea de repostería Daliza, ideales para detalles, mesas de postres y antojos. Pequeñas en tamaño, grandes en intención. Las trufas Daliza son perfectas para regalar, compartir o sumar un toque sofisticado y dulce a cualquier celebración.', 'reposteria', 'chocolatería', null, true, 134),
  ('hojaldre-de-arequipe-y-queso', 'Hojaldre de arequipe y queso', 'Hojaldre de arequipe y queso.', 'Pieza de hojaldre con combinación de arequipe y queso, ideal para desayunos, onces y antojos. El contraste que siempre funciona: arequipe y queso reunidos en una pieza de hojaldre pensada para quienes disfrutan el equilibrio entre lo dulce y lo salado.', 'panaderia', 'hojaldres dulces', null, true, 135),
  ('hojaldre-de-bocadillo-y-queso', 'Hojaldre de bocadillo y queso', 'Hojaldre de bocadillo y queso.', 'Pieza de hojaldre con bocadillo y queso, una combinación clásica de la panadería colombiana. Una combinación que sabe a tradición: bocadillo y queso en una pieza de hojaldre ideal para acompañar el café, compartir en familia o disfrutar como un antojo especial.', 'panaderia', 'hojaldres dulces', null, true, 136),
  ('hojaldre-de-pastelera-y-bocadillo', 'Hojaldre de pastelera y bocadillo', 'Hojaldre con crema pastelera y bocadillo.', 'Pieza de hojaldre dulce con combinación de pastelera y bocadillo. Una mezcla de sabores tradicionales con un toque más delicado: crema pastelera y bocadillo se encuentran en un hojaldre pensado para sorprender desde el primer bocado.', 'panaderia', 'hojaldres dulces', null, true, 137),
  ('palito-de-queso', 'Palito de queso', 'Palito de queso.', 'Pieza salada de la línea de hojaldres con queso como protagonista. Práctico, apetecible y perfecto para cualquier hora. El palito de queso Daliza es una opción ideal para acompañar bebidas, compartir o calmar un antojo salado.', 'panaderia', 'hojaldres salados', null, true, 138),
  ('danesa-de-breva', 'Danesa de breva', 'Danesa de breva.', 'Pieza de la línea de hojaldres dulces con breva como sabor distintivo. Una danesa con carácter frutal y elegante, donde la breva aporta un toque especial a una pieza perfecta para acompañar el café o disfrutar como postre.', 'panaderia', 'hojaldres dulces', null, true, 139),
  ('tiples-de-bocadillo-y-queso', 'Tiples de bocadillo y queso', 'Tiples de bocadillo y queso.', 'Pieza de hojaldre con bocadillo y queso registrada en la fuente como tiples. Una combinación colombiana en una presentación especial: bocadillo y queso reunidos en una pieza pensada para compartir y disfrutar un contraste dulce-salado que siempre conquista.', 'panaderia', 'hojaldres dulces', null, true, 140),
  ('hojaldre-de-bocadillo', 'Hojaldre de bocadillo', 'Hojaldre de bocadillo.', 'Pieza de hojaldre dulce con bocadillo como sabor principal. Un clásico sencillo y lleno de sabor: hojaldre y bocadillo en una combinación ideal para acompañar una bebida caliente y disfrutar una pausa dulce.', 'panaderia', 'hojaldres dulces', null, true, 141),
  ('pastel-de-carne', 'Pastel de carne', 'Pastel de carne.', 'Pieza salada de la línea de hojaldres con relleno de carne. Una opción salada y reconfortante para cualquier momento del día. El pastel de carne Daliza es ideal para una pausa rápida, una merienda o un antojo con más carácter.', 'panaderia', 'hojaldres salados', null, true, 142),
  ('pastel-de-pollo', 'Pastel de pollo', 'Pastel de pollo.', 'Pieza salada de la línea de hojaldres con relleno de pollo. Una alternativa práctica y deliciosa para quienes prefieren sabores salados. El pastel de pollo Daliza acompaña perfectamente una merienda, un desayuno tardío o una pausa durante el día.', 'panaderia', 'hojaldres salados', null, true, 143),
  ('corazones', 'Corazones', 'Corazones de hojaldre.', 'Pieza de la línea de hojaldres identificada comercialmente como corazones. Una pieza con una presentación encantadora, perfecta para acompañar un café, regalar un detalle o sumar algo especial a una mesa de panadería.', 'panaderia', 'hojaldres dulces', null, true, 144),
  ('pastel-hawaiano', 'Pastel hawaiano', 'Pastel hawaiano.', 'Pieza salada de la línea de hojaldres con perfil hawaiano. Una opción de hojaldre con un perfil diferente y lleno de contraste. El pastel hawaiano Daliza es ideal para quienes disfrutan combinaciones saladas con un toque especial.', 'panaderia', 'hojaldres salados', null, true, 145)
insert into public.product_locations (product_id, location_id)
